import java.io.*;
import java.util.*;

public class Main {
    static BufferedReader in = new BufferedReader(new InputStreamReader(System.in));
    static StringTokenizer tokens = new StringTokenizer("");

    static String next() throws IOException {
        while (!tokens.hasMoreTokens()) {
            tokens = new StringTokenizer(in.readLine());
        }
        return tokens.nextToken();
    }

    static void bitAdd(long[] t, int i, long x) {
        int n = t.length - 1;
        for (; i <= n; i += i & -i) t[i] += x;
    }

    static long bitSum(long[] t, int i) {
        long s = 0;
        for (; i > 0; i -= i & -i) s += t[i];
        return s;
    }

    public static void main(String[] args) throws IOException {
        long n = Long.parseLong(next());
        long d = Long.parseLong(next());
        long[] a = new long[(int) n];
        for (int i = 0; i < a.length; i++) a[i] = Long.parseLong(next());

        int cn = (int) n;
        long[] u = a.clone();
        Arrays.sort(u);
        int m = 0;
        for (int i = 0; i < cn; i++) {
            if (i == 0 || u[i] != u[i - 1]) u[m++] = u[i];
        }
        long[] t = new long[m + 1];
        long total = 0;
        for (int i = 0; i < cn; i++) {
            long v = a[i];
            int lo1 = 0, hi1 = m;
            while (lo1 < hi1) {
                int mid = (lo1 + hi1) / 2;
                if (u[mid] <= v + d) lo1 = mid + 1;
                else hi1 = mid;
            }
            int lo2 = 0, hi2 = m;
            while (lo2 < hi2) {
                int mid = (lo2 + hi2) / 2;
                if (u[mid] < v - d) lo2 = mid + 1;
                else hi2 = mid;
            }
            total += bitSum(t, lo1) - bitSum(t, lo2);
            bitAdd(t, Arrays.binarySearch(u, 0, m, v) + 1, 1);
        }
        System.out.println(total);
    }
}
